"""Parse a note's simple YAML-like front matter and body."""

from __future__ import annotations


def _is_delimiter(line: str) -> bool:
    """Return True for a front-matter delimiter line."""
    return line.lstrip("\ufeff").strip() == "---"


def parse_page(text: str) -> dict:
    """Parse one note.

    The first two ``---`` lines delimit the front matter.  ``title`` and
    ``date`` are returned as strings, ``tags`` as a list of comma-separated,
    stripped values.  Everything after the closing delimiter line is returned
    unchanged as ``body`` (including blank lines and line endings).
    """
    lines = text.splitlines(keepends=True)

    opening = None
    closing = None
    for index, line in enumerate(lines):
        if _is_delimiter(line):
            if opening is None:
                opening = index
            else:
                closing = index
                break

    # No complete front matter: expose the whole input as the body.
    if opening is None or closing is None:
        return {"title": "", "date": "", "tags": [], "body": text}

    meta = {}
    for line in lines[opening + 1 : closing]:
        key, separator, value = line.partition(":")
        if separator:
            meta[key.strip().lower()] = value.strip()

    if "tags" in meta and meta["tags"]:
        tags = [tag.strip() for tag in meta["tags"].split(",")]
    else:
        tags = []

    body = "".join(lines[closing + 1 :])

    return {
        "title": meta.get("title", ""),
        "date": meta.get("date", ""),
        "tags": tags,
        "body": body,
    }

